import React from 'react';
import { Link } from 'react-router-dom';

const Home = () => {
  const categories = ['HTML', 'CSS', 'Java', 'JavaScript', 'Python', 'C', 'C++'];

  return (
    <div className="container mx-auto p-8">
      <h1 className="text-4xl font-bold text-center mb-8">Welcome to Shiksha Dakshaka</h1>
      <p className="text-center mb-8">Test your programming knowledge with our quizzes!</p>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {categories.map(category => (
          <Link key={category} to={`/quiz/${category}`} className="bg-white p-6 rounded shadow hover:shadow-lg">
            <h2 className="text-2xl font-bold">{category} Quiz</h2>
            <p>Test your {category} skills</p>
          </Link>
        ))}
      </div>
    </div>
  );
};

export default Home;
